xml.Script:
        clRed     := 'C80000';
        clOrange  := 'FF800A';
        clBlue1   := '0100C8';
        clBlue2   := '0000C8';
        clBlue3   := '0001C8';
        clGreen1  := '019600';
        clGreen2  := '009600';
        clGreen3  := '009601';
        clYellow  := 'FFFF00';
        clWhite   := 'FFFFFF';

        H := 0.4;
        D := H;
        R0 := D * 0.7;
        R1 := R0 + D * 2 / 3;
        D1 := H / 3;
        sAngle := Pi * 7 / 9;

        ca := cos(Pi/9);
        sa := sin(Pi/9);

        procedure AddVertex(ax, ay);
        begin
            x[i] := ax * ca + ay * sa;
            y[i] :=-ax * sa + ay * ca;
            Inc(i);
        end;
        i := 0;
        AddVertex( R0,-D);
        AddVertex( R1,-D);
        AddVertex( R1, D);
        AddVertex( R0, D);
        for i := 4 to 7 do begin
            x[i] :=-x[7 - i];
            y[i] := y[7 - i];
        end;
